import React,{useEffect,useMemo,useState} from 'react';
import QRCode from 'qrcode';
import * as XLSX from 'xlsx';
import {configured,supabase} from './supabase.js';
import {seed} from './seed.js';
import {cacheState,clearPendingSync,getPendingSync,isOnline,loadCachedState,markPendingSync} from './offline.js';

const clone=x=>JSON.parse(JSON.stringify(x));
const uid=(p='id')=>`${p}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
const fmtDate=v=>v?new Intl.DateTimeFormat('tr-TR').format(new Date(v)):'-';
const roleLabel={system_admin:'Sistem Yöneticisi',company_admin:'Firma Yöneticisi',participant:'Katılımcı'};
const statusLabel={assigned:'Atandı',in_progress:'Devam Ediyor',completed:'Tamamlandı',overdue:'Gecikti',expired:'Süresi Doldu',revoked:'İptal'};
const onlyDigits=s=>String(s||'').replace(/\D/g,'');
const examQuestions=c=>[...(c.questions||[]),...(c.customQuestions||[])];
const daysFromNow=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};

function upgradeState(raw){
 const s=raw?.courses?clone(raw):clone(seed);
 const oldCourses=new Map((s.courses||[]).map(c=>[c.id,c]));
 s.meta={...(s.meta||{}),...seed.meta,version:2};
 s.categories=clone(seed.categories);if(!s.categories.some(c=>c.id==='custom'))s.categories.push({id:'custom',name:'Özel Eğitimler'});
 s.courses=seed.courses.map(base=>{const old=oldCourses.get(base.id)||{};return {...clone(base),...old,customContents:old.customContents||[],customQuestions:old.customQuestions||[]}});
 for(const old of oldCourses.values())if(!s.courses.some(c=>c.id===old.id))s.courses.push(old);
 s.users=(s.users||[]).map(u=>({...u,phone:u.phone||'',employeeNo:u.employeeNo||'',workforce:u.workforce||'white',employmentType:u.employmentType||'employee',contractorCompany:u.contractorCompany||'',tc:u.tc||u.loginCode||'',loginCode:u.loginCode||u.tc||'',loginEmail:u.loginEmail||u.email||'',kvkkConsentAt:u.kvkkConsentAt||null,kvkkConsentEvidence:u.kvkkConsentEvidence||null}));
 s.mobileAccess=s.mobileAccess||[];
 s.settings={...seed.settings,...(s.settings||{}),version:'2.8.0',certificatePrefix:(s.settings||{}).certificatePrefix||'ARYA',defaultDueDays:(s.settings||{}).defaultDueDays||30,defaultLinkDays:(s.settings||{}).defaultLinkDays||30,companyBranding:(s.settings||{}).companyBranding??true,certificateSigner:(s.settings||{}).certificateSigner||'ARYA Akademi',certificateTitle:(s.settings||{}).certificateTitle||'Başarı Sertifikası',coursePrices:(s.settings||{}).coursePrices||{},certificateNote:(s.settings||{}).certificateNote||'',modulePermissions:(s.settings||{}).modulePermissions||{},coursePermissions:(s.settings||{}).coursePermissions||{},managementMessages:(s.settings||{}).managementMessages||[],announcementReads:(s.settings||{}).announcementReads||{},kvkkAudit:(s.settings||{}).kvkkAudit||[],kvkkAccepted:(s.settings||{}).kvkkAccepted||{},certificateApprovals:(s.settings||{}).certificateApprovals||{},blogs:(s.settings||{}).blogs||[],blogTopics:(s.settings||{}).blogTopics||[]};s.companySettings=s.companySettings||{};
 return s;
}
function productionSeed(p){const x=upgradeState(clone(seed));x.companies=x.companies.filter(c=>c.id==='c1');x.users=[{id:p.id,name:p.full_name||p.email,email:p.email,role:p.role||'participant',companyId:p.company_id||'c1',department:'',title:'',phone:'',employeeNo:'',workforce:'white',employmentType:'employee',contractorCompany:'',active:true}];x.assignments=[];x.certificates=[];x.mobileAccess=[];return x}

function useAcademy(){
 const [state,setStateRaw]=useState(()=>upgradeState(loadCachedState(clone(seed))));
 const [ready,setReady]=useState(!configured),[session,setSession]=useState(null),[profile,setProfile]=useState(null),[remote,setRemote]=useState(false),[online,setOnline]=useState(isOnline());
 const setState=v=>setStateRaw(prev=>upgradeState(typeof v==='function'?v(prev):v));
 const syncNow=async payload=>{if(!configured||!isOnline())return false;try{const {error}=await supabase.from('academy_state').upsert({id:'main',payload,updated_at:new Date().toISOString()});if(error)throw error;clearPendingSync();return true}catch{return false}};
 useEffect(()=>{const on=async()=>{setOnline(true);const q=getPendingSync();if(q?.state)await syncNow(q.state)};const off=()=>setOnline(false);window.addEventListener('online',on);window.addEventListener('offline',off);return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',off)}},[]);
 useEffect(()=>{if(!configured)return;let sub;(async()=>{try{const {data}=await supabase.auth.getSession();setSession(data.session||null);if(data.session)await boot(data.session.user)}finally{setReady(true)};const r=supabase.auth.onAuthStateChange(async(_,ss)=>{setSession(ss);if(ss)await boot(ss.user);else{setProfile(null);setRemote(false)}});sub=r.data.subscription})();return()=>sub?.unsubscribe()},[]);
 async function boot(user){
  let p=null,r=null,mobile=[];
  if(isOnline()){
   try{p=(await supabase.from('profiles').select('*').eq('id',user.id).maybeSingle()).data||null;if(p?.role==='participant'){try{await supabase.rpc('claim_first_academy_admin');p=(await supabase.from('profiles').select('*').eq('id',user.id).maybeSingle()).data||p}catch{}}}catch{}
   try{r=(await supabase.from('academy_state').select('payload').eq('id','main').maybeSingle()).data||null}catch{}
   if(p?.role&&p.role!=='participant')try{mobile=(await supabase.from('mobile_access').select('*').order('created_at',{ascending:false})).data||[]}catch{}
  }
  let cachedProfile=null;try{cachedProfile=JSON.parse(localStorage.getItem('aryaAcademyProfile')||'null')}catch{}
  const fallback=p||cachedProfile||{id:user.id,email:user.email,full_name:user.user_metadata?.full_name||user.email,role:'participant'};setProfile(fallback);if(p)try{localStorage.setItem('aryaAcademyProfile',JSON.stringify(p))}catch{}
  let next=r?.payload?.courses?upgradeState(r.payload):upgradeState(loadCachedState(productionSeed(fallback)));
  if(mobile.length)next.mobileAccess=mobile.map(x=>({id:x.id,token:x.token,employeeName:x.employee_name,employeeNo:x.employee_no,phone:x.phone,companyId:x.company_id,courseId:x.course_id,due:x.due_date,expiresAt:x.expires_at,status:x.status,progress:x.progress,score:x.score,certificateNo:x.certificate_no,completedAt:x.completed_at}));
  setStateRaw(next);cacheState(next);setRemote(true);
 }
 useEffect(()=>{cacheState(state);if(!remote)return;const t=setTimeout(async()=>{if(!isOnline()){markPendingSync(state);return}const clean={...state,mobileAccess:[]};const ok=await syncNow(clean);if(!ok)markPendingSync(clean)},700);return()=>clearTimeout(t)},[state,remote]);
 return {state,setState,ready,session,profile,remote,online,async signOut(){if(configured&&isOnline())await supabase.auth.signOut()},async login(email,password){if(!isOnline())return{error:{message:'İlk giriş için internet bağlantısı gerekir.'}};let loginEmail=email; if(!String(email).includes('@')){const code=String(email).trim().toUpperCase();try{const {data,error}=await supabase.functions.invoke('resolve-login-code',{body:{code}});if(!error&&data?.email)loginEmail=data.email;else{const person=this.state?.users?.find(u=>String(u.loginCode||u.tc||'').toUpperCase()===code);const firm=this.state?.companies?.find(c=>String(c.loginCode||'').toUpperCase()===code);loginEmail=person?.loginEmail||person?.email||firm?.loginEmail||firm?.email||''}}catch{const person=this.state?.users?.find(u=>String(u.loginCode||u.tc||'').toUpperCase()===code);const firm=this.state?.companies?.find(c=>String(c.loginCode||'').toUpperCase()===code);loginEmail=person?.loginEmail||person?.email||firm?.loginEmail||firm?.email||''}if(!loginEmail)return{error:{message:'Giriş kodu / T.C. Kimlik No bulunamadı.'}}}return supabase.auth.signInWithPassword({email:loginEmail,password})},async signup(email,password,name){if(!isOnline())return{error:{message:'Hesap oluşturmak için internet bağlantısı gerekir.'}};return supabase.auth.signUp({email,password,options:{data:{full_name:name}}})}};
}

function Login({api}){const[mode,setMode]=useState('login'),[f,setF]=useState({name:'',email:'',password:''}),[msg,setMsg]=useState('');const submit=async e=>{e.preventDefault();setMsg('');const r=mode==='login'?await api.login(f.email,f.password):await api.signup(f.email,f.password,f.name);if(r.error)setMsg(r.error.message);else if(mode==='signup')setMsg('Kayıt başvurunuz alındı. Yönetici onayından sonra giriş izniniz e-posta ile bildirilecektir.')};if(!configured)return <DemoGate onEnter={()=>api.setDemo?.(true)}/>;return <div className="auth"><div className="auth-card"><img src="/arya-logo.png"/><h1>ARYA Akademi</h1><p>Kurumsal Çevre Eğitim ve Yetkinlik Yönetimi</p><div className="tabs"><button className={mode==='login'?'active':''} onClick={()=>setMode('login')}>Giriş</button><button className={mode==='signup'?'active':''} onClick={()=>setMode('signup')}>Kayıt</button></div><form onSubmit={submit}>{mode==='signup'&&<input placeholder="Ad Soyad" value={f.name} onChange={e=>setF({...f,name:e.target.value})} required/>}<input type="text" placeholder="E-posta, Firma Giriş Kodu veya T.C. Kimlik No" value={f.email} onChange={e=>setF({...f,email:e.target.value})} required/><input type="password" placeholder="Şifre" value={f.password} onChange={e=>setF({...f,password:e.target.value})} minLength="6" required/><button className="primary">{mode==='login'?'Giriş Yap':'Hesap Oluştur'}</button>{msg&&<div className="notice">{msg}</div>}</form><div className="auth-links"><a href="/?kiosk=1">Ortak Tablet / Kiosk</a></div></div></div>}
function DemoGate({onEnter}){return <div className="auth"><div className="auth-card"><img src="/arya-logo.png"/><h1>ARYA Akademi V2.8.0</h1><p>V2.8.0 bağlantı kontrol modu. Supabase ayarları yoksa yalnızca demo açılır.</p><button className="primary" onClick={onEnter}>Demo Sisteme Gir</button></div></div>}

export default function App(){
 const join=new URLSearchParams(location.search).get('join');const kiosk=new URLSearchParams(location.search).get('kiosk');const verify=new URLSearchParams(location.search).get('verify');
 if(join)return <MobileTraining token={join}/>;if(kiosk)return <Kiosk/>;
 const api=useAcademy();const[demo,setDemo]=useState(false),[page,setPage]=useState('Ana Panel'),[toast,setToast]=useState('');api.setDemo=setDemo;
 if(verify)return <VerifyPage id={verify} localState={api.state}/>;if(!api.ready)return <div className="loader">ARYA Akademi yükleniyor…</div>;if(configured&&!api.session)return <Login api={api}/>;if(!configured&&!demo)return <Login api={api}/>;
 const storedRole=api.profile?.role||'participant';const role=storedRole==='participant'&&api.profile?.email?.toLowerCase()==='guven@guvenozkan.com'?'system_admin':storedRole;const found=api.state.users?.find(u=>u.email===api.profile?.email||u.loginEmail===api.profile?.email);const currentUser=found?{...found,role}:{id:api.profile?.id||'u1',name:api.profile?.full_name||'Sistem Yöneticisi',email:api.profile?.email||'',role,companyId:api.profile?.company_id||'c1'};
 const rawNav=role==='participant'?['Ana Panel','Eğitim Kataloğu']:role==='company_admin'?['Ana Panel','Müşterim','Eğitim Kataloğu','Yönetim','Ayarlar']:['Ana Panel','Katılımcılar','Eğitim Kataloğu','Yönetim','Ayarlar'];const permKey=role==='participant'?`participant:${currentUser.id}`:role==='company_admin'?`company:${currentUser.companyId}`:currentUser.id;const allowedModules=api.state.settings?.modulePermissions?.[permKey];const nav=role==='system_admin'||!allowedModules?rawNav:rawNav.filter(n=>n==='Ana Panel'||allowedModules.includes(n));
 const notify=m=>{setToast(m);setTimeout(()=>setToast(''),2600)};
 if(role!=='system_admin'&&!currentUser.kvkkConsentAt&&!api.state.settings?.kvkkAccepted?.[currentUser.id])return <KvkkConsentGate s={api.state} setS={api.setState} user={currentUser} notify={notify}/>;
 return <div className="app"><aside><div className="brand"><img src="/arya-logo.png"/><div><b>ARYA</b><span>AKADEMİ V2.8.0</span></div></div><nav>{nav.map(n=><button key={n} className={page===n?'active':''} onClick={()=>setPage(n)}>{n}</button>)}</nav><div className="aside-foot"><span>{roleLabel[role]}</span><small>{api.remote?'Supabase • Canlı':'Yerel Demo'} • {api.online?'Çevrimiçi':'Çevrimdışı'}</small>{configured&&<button onClick={api.signOut}>Çıkış</button>}</div></aside><main><Top title={page} user={currentUser}/><section className="content"><Router page={page} s={api.state} setS={api.setState} user={currentUser} role={role} online={api.online} notify={notify}/></section></main>{toast&&<div className="toast">{toast}</div>}</div>
}
function Top({title,user}){return <header><div><h2>{title}</h2></div><div className="user-chip"><span>{user?.name?.slice(0,1)||'A'}</span><div><b>{user?.name||'Kullanıcı'}</b><small>{user?.department||'ARYA Akademi'}</small></div></div></header>}
function Router(p){return ({'Ana Panel':<Dashboard {...p}/>,Dashboard:<Dashboard {...p}/>,Katılımcılar:<Companies {...p}/>,Müşterim:<Companies {...p}/>, 'Kullanıcı Yetkileri':<AccessControl {...p}/>, 'Eğitim Kataloğu':<Catalog {...p}/>,Eğitimler:<Assignments {...p}/>,Atamalar:<Assignments {...p}/>, 'Eğitim Matrisi':<Matrix {...p}/>,Sertifikalar:<Certificates {...p}/>,Raporlar:<Reports {...p}/>,Duyurular:<Announcements {...p}/>, 'Mobil Katılım':<MobileAdmin {...p}/>,Eğitmenler:<Instructors {...p}/>,Yönetim:<Management {...p}/>,Blog:<Blog {...p}/>,Ayarlar:<Settings {...p}/>})[p.page]}
const Card=({n,t})=><div className="stat"><strong>{n}</strong><span>{t}</span></div>;const Panel=({title,children})=><div className="panel"><div className="panel-title"><h3>{title}</h3></div>{children}</div>;const Pill=({children,kind=''})=><span className={`pill ${kind}`}>{children}</span>;

function Dashboard({s,setS,user,role}){return <><Panel title="Bilgi Bankası"><KnowledgeBaseViewer s={s} user={user} role={role}/></Panel><div className="grid2"><Panel title="Duyurular">{(s.announcements||[]).filter(a=>!a.companyIds?.length||a.companyIds.includes(user.companyId)).map(a=><div className="announce big unread" key={a.id}><b>● {a.title}</b><p>{a.text}</p><small>{fmtDate(a.date)}</small></div>)}</Panel><Panel title="Yönetime Mesaj"><MessageToManagement s={s} setS={setS} user={user}/></Panel></div></>}
function MessageToManagement({s,setS,user}){const[msg,setMsg]=useState('');const send=e=>{e.preventDefault();if(!msg.trim())return;const row={id:uid('msg'),userId:user.id,userName:user.name,companyId:user.companyId,text:msg.trim(),date:new Date().toISOString()};setS(x=>({...x,settings:{...x.settings,managementMessages:[...(x.settings.managementMessages||[]),row]}}));setMsg('')};return <form className="form" onSubmit={send}><textarea rows="4" value={msg} onChange={e=>setMsg(e.target.value)} placeholder="Yönetime mesajınızı yazın"/><button className="primary">Mesaj Gönder</button></form>}
function AccessControl({s,setS,notify}){const[targetType,setTargetType]=useState('company'),[targetId,setTargetId]=useState(s.companies[0]?.id||'');const modules=['Ana Panel','Eğitim Kataloğu','Ayarlar'];const targets=targetType==='company'?s.companies:s.users.filter(u=>u.role==='participant');useEffect(()=>{if(!targets.some(x=>x.id===targetId))setTargetId(targets[0]?.id||'')},[targetType,s.companies.length,s.users.length]);const key=`${targetType}:${targetId}`;const selectedModules=s.settings.modulePermissions?.[key]||modules;const selectedCourses=s.settings.coursePermissions?.[key]||s.courses.map(c=>c.id);const save=e=>{e.preventDefault();const f=new FormData(e.currentTarget),modulePermissions={...(s.settings.modulePermissions||{}),[key]:f.getAll('modules')},coursePermissions={...(s.settings.coursePermissions||{}),[key]:f.getAll('courses')};setS(x=>({...x,settings:{...x.settings,modulePermissions,coursePermissions}}));notify('Kullanıcı atamaları kaydedildi.')};return <Panel title="Kullanıcı Atamaları"><div className="toolbar split"><div className="tabs"><button className={targetType==='company'?'active':''} onClick={()=>setTargetType('company')}>Firmalar</button><button className={targetType==='participant'?'active':''} onClick={()=>setTargetType('participant')}>Katılımcılar</button></div><select value={targetId} onChange={e=>setTargetId(e.target.value)}>{targets.map(x=><option key={x.id} value={x.id}>{x.name}{targetType==='participant'?` • ${s.companies.find(c=>c.id===x.companyId)?.name||''}`:''}</option>)}</select></div>{targetId?<form className="permission-card" onSubmit={save}><h4>Modül Erişimi</h4><div className="check-grid">{modules.map(m=><label key={m}><input type="checkbox" name="modules" value={m} defaultChecked={selectedModules.includes(m)}/>{m}</label>)}</div><h4>Eğitim Erişimi</h4><div className="check-grid">{s.courses.map(c=><label key={c.id}><input type="checkbox" name="courses" value={c.id} defaultChecked={selectedCourses.includes(c.id)}/>{c.title}</label>)}</div><button className="primary">Atamaları Kaydet</button></form>:<Empty title="Kayıt bulunamadı" text="Önce firma veya katılımcı kaydı oluşturun."/>}</Panel>}
function Catalog({s,setS,role,user,online,notify}){const[selected,setSelected]=useState(null),[createOpen,setCreateOpen]=useState(false);const coursePermKey=role==='participant'?`participant:${user.id}`:role==='company_admin'?`company:${user.companyId}`:user.id;const permitted=role==='system_admin'?s.courses:s.courses.filter(x=>!(s.settings.coursePermissions?.[coursePermKey])||s.settings.coursePermissions[coursePermKey].includes(x.id));const c=selected&&permitted.find(x=>x.id===selected);const addCourse=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const course={id:uid('course'),title:f.get('title'),titleEn:f.get('titleEn')||f.get('title'),categoryId:'custom',duration:Number(f.get('duration')||30),level:'Özel',validMonths:Number(f.get('validMonths')||12),passing:Number(f.get('passing')||70),mandatory:false,summary:f.get('summary')||'Kuruma özel eğitim.',fixed:false,modules:[],questions:[],customContents:[],customQuestions:[]};setS(x=>({...x,courses:[...x.courses,course]}));setCreateOpen(false);setSelected(course.id);notify('Boş özel eğitim oluşturuldu. İçerik ve sınav sorularını şimdi ekleyebilirsiniz.')};return <><div className="toolbar split"><div><b>{permitted.length}</b> eğitim</div>{role!=='participant'&&<button className="primary" onClick={()=>setCreateOpen(true)}>+ Boş Eğitim Oluştur</button>}</div><div className="course-grid">{permitted.map(c=><button className="course" key={c.id} onClick={()=>setSelected(c.id)}><div className="course-top"><span>{s.categories.find(x=>x.id===c.categoryId)?.name||'Özel Eğitim'}</span>{!c.fixed&&<Pill kind="warn">Özel Eğitim</Pill>}</div><h3>{c.title}</h3><p>{c.summary}</p><div className="course-meta"><span>{c.duration} dk</span><span>{(c.modules||[]).length+(c.customContents?.length||0)} bölüm</span><span>{examQuestions(c).length} soru</span><span>Geçme %{c.passing}</span></div></button>)}</div>{c&&<CourseModal c={c} s={s} setS={setS} canEdit={role!=='participant'} online={online} notify={notify} close={()=>setSelected(null)}/>} {createOpen&&<Modal title="Yeni Boş Eğitim" close={()=>setCreateOpen(false)}><form className="form" onSubmit={addCourse}><input name="title" placeholder="Eğitim adı" required/><input name="titleEn" placeholder="English title (opsiyonel)"/><textarea name="summary" placeholder="Kısa açıklama" rows="3"/><div className="form2"><label>Süre (dk)<input name="duration" type="number" min="1" defaultValue="30"/></label><label>Geçme puanı (%)<input name="passing" type="number" min="0" max="100" defaultValue="70"/></label></div><label>Sertifika geçerliliği (ay)<input name="validMonths" type="number" min="1" max="120" defaultValue="12"/></label><div className="fixed-note">Bu eğitim tamamen boş oluşturulur. Eğitim içeriğini ve sınav sorularını siz ekleyebilirsiniz.</div><button className="primary">Eğitimi Oluştur</button></form></Modal>}</>}
function CourseModal({c,s,setS,canEdit,online,notify,close}){const[tab,setTab]=useState('content'),[uploading,setUploading]=useState(false);const updateCourse=e=>{e.preventDefault();const f=new FormData(e.currentTarget);setS(x=>({...x,courses:x.courses.map(k=>k.id===c.id?{...k,title:f.get('title'),titleEn:f.get('titleEn')||f.get('title'),summary:f.get('summary'),duration:Number(f.get('duration')||k.duration),passing:Number(f.get('passing')||k.passing),validMonths:Number(f.get('validMonths')||k.validMonths)}:k)}));notify('Eğitim bilgileri güncellendi.')};const updateModule=(e,id)=>{e.preventDefault();const f=new FormData(e.currentTarget);setS(x=>({...x,courses:x.courses.map(k=>k.id===c.id?{...k,modules:(k.modules||[]).map(m=>m.id===id?{...m,title:f.get('title'),body:f.get('body'),bullets:String(f.get('bullets')||'').split('\n').map(v=>v.trim()).filter(Boolean)}:m)}:k)}));notify('Eğitim bölümü güncellendi.')};const updateQuestion=(e,id)=>{e.preventDefault();const f=new FormData(e.currentTarget);const patch=q=>q.id===id?{...q,text:f.get('q'),options:[f.get('a'),f.get('b'),f.get('c'),f.get('d')],answer:Number(f.get('answer'))}:q;setS(x=>({...x,courses:x.courses.map(k=>k.id===c.id?{...k,questions:(k.questions||[]).map(patch),customQuestions:(k.customQuestions||[]).map(patch)}:k)}));notify('Sınav sorusu güncellendi.')};const addText=e=>{e.preventDefault();const f=new FormData(e.currentTarget),item={id:uid('custom'),type:f.get('type'),title:f.get('title'),body:f.get('body'),url:f.get('url')||'',createdAt:new Date().toISOString(),fixed:false};setS(x=>({...x,courses:x.courses.map(k=>k.id===c.id?{...k,customContents:[...(k.customContents||[]),item]}:k)}));e.currentTarget.reset();notify('Ek içerik eklendi.')};const upload=async e=>{const file=e.target.files?.[0];if(!file)return;if(!configured){notify('Dosya yükleme canlı Supabase bağlantısında kullanılabilir.');return}if(!online){notify('Dosya yüklemek için internet bağlantısı gerekir.');return}setUploading(true);try{const path=`custom/${c.id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error}=await supabase.storage.from('academy-content').upload(path,file);if(error)throw error;const {data}=supabase.storage.from('academy-content').getPublicUrl(path);const item={id:uid('file'),type:'file',title:file.name,body:`${Math.round(file.size/1024)} KB`,url:data.publicUrl,createdAt:new Date().toISOString(),fixed:false};setS(x=>({...x,courses:x.courses.map(k=>k.id===c.id?{...k,customContents:[...(k.customContents||[]),item]}:k)}));notify('Dosya yüklendi.')}catch(err){notify('Yükleme hatası: '+err.message)}finally{setUploading(false);e.target.value=''}};const addQ=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const q={id:uid('q'),text:f.get('q'),options:[f.get('a'),f.get('b'),f.get('c'),f.get('d')],answer:Number(f.get('answer')),fixed:false};setS(x=>({...x,courses:x.courses.map(k=>k.id===c.id?{...k,customQuestions:[...(k.customQuestions||[]),q]}:k)}));e.currentTarget.reset();notify('Ek sınav sorusu eklendi.')};return <Modal title={c.title} close={close} wide><div className="tabs"><button className={tab==='content'?'active':''} onClick={()=>setTab('content')}>Eğitim İçeriği</button><button className={tab==='exam'?'active':''} onClick={()=>setTab('exam')}>Sınav ({examQuestions(c).length})</button>{canEdit&&<button className={tab==='courseEdit'?'active':''} onClick={()=>setTab('courseEdit')}>Eğitimi Düzenle</button>}{canEdit&&<button className={tab==='examEdit'?'active':''} onClick={()=>setTab('examEdit')}>Sınavı Düzenle</button>}{canEdit&&<button className={tab==='editor'?'active':''} onClick={()=>setTab('editor')}>İçerik / Soru Ekle</button>}</div>{tab==='content'&&<div className="learning">{c.modules.map((m,i)=><article className="lesson" key={m.id}><span>BÖLÜM {i+1}</span><h3>{m.title}</h3><p>{m.body}</p><ul>{m.bullets.map(b=><li key={b}>{b}</li>)}</ul></article>)}{(c.customContents||[]).length>0&&<><h3>Firma / Yönetici Ek İçerikleri</h3>{c.customContents.map(x=><article className="lesson custom" key={x.id}><span>EK İÇERİK • {x.type}</span><h3>{x.title}</h3>{x.body&&<p>{x.body}</p>}{x.url&&<a href={x.url} target="_blank" rel="noreferrer">İçeriği Aç</a>}</article>)}</>}{c.sourceRefs?.length>0&&<div className="source-box"><b>Referans çerçevesi</b>{c.sourceRefs.map(r=><span key={r}>{r}</span>)}</div>}</div>}{tab==='exam'&&<div className="question-list">{examQuestions(c).map((q,i)=><div className="question-preview" key={q.id}><div><b>{i+1}. {q.text}</b></div><ol type="A">{q.options.map((o,j)=><li className={j===q.answer?'answer':''} key={o}>{o}</li>)}</ol></div>)}</div>}{tab==='courseEdit'&&canEdit&&<div className="learning"><Panel title="Eğitim Bilgileri"><form className="form" onSubmit={updateCourse}><input name="title" defaultValue={c.title} placeholder="Eğitim adı" required/><input name="titleEn" defaultValue={c.titleEn||''} placeholder="English title"/><textarea name="summary" defaultValue={c.summary||''} rows="3"/><div className="form2"><label>Süre (dk)<input name="duration" type="number" min="1" defaultValue={c.duration}/></label><label>Geçme puanı (%)<input name="passing" type="number" min="0" max="100" defaultValue={c.passing}/></label></div><label>Sertifika geçerliliği (ay)<input name="validMonths" type="number" min="1" max="120" defaultValue={c.validMonths||12}/></label><button className="primary">Eğitim Bilgilerini Kaydet</button></form></Panel>{(c.modules||[]).map((m,i)=><Panel key={m.id} title={`Bölüm ${i+1} • Düzenle`}><form className="form" onSubmit={e=>updateModule(e,m.id)}><input name="title" defaultValue={m.title} required/><textarea name="body" defaultValue={m.body||''} rows="6"/><label>Madde işaretleri (her satıra bir madde)<textarea name="bullets" defaultValue={(m.bullets||[]).join('\n')} rows="5"/></label><button className="primary">Bölümü Kaydet</button></form></Panel>)}</div>}{tab==='examEdit'&&canEdit&&<div className="question-list">{examQuestions(c).map((q,i)=><Panel key={q.id} title={`${i+1}. Soru • Düzenle`}><form className="form" onSubmit={e=>updateQuestion(e,q.id)}><textarea name="q" defaultValue={q.text} required/><input name="a" defaultValue={q.options?.[0]||''} required/><input name="b" defaultValue={q.options?.[1]||''} required/><input name="c" defaultValue={q.options?.[2]||''} required/><input name="d" defaultValue={q.options?.[3]||''} required/><select name="answer" defaultValue={String(q.answer)}><option value="0">Doğru: A</option><option value="1">Doğru: B</option><option value="2">Doğru: C</option><option value="3">Doğru: D</option></select><button className="primary">Soruyu Kaydet</button></form></Panel>)}</div>}{tab==='editor'&&canEdit&&<div className="editor-grid"><Panel title="Ek Eğitim İçeriği"><form className="form" onSubmit={addText}><select name="type"><option value="text">Metin</option><option value="video">Video Linki</option><option value="document">Doküman Linki</option><option value="link">Web Linki</option></select><input name="title" placeholder="İçerik başlığı" required/><textarea name="body" placeholder="Açıklama / eğitim metni" rows="5"/><input name="url" placeholder="https://... (opsiyonel)"/><button className="primary">İçeriği Ekle</button></form><label className="upload-box">{uploading?'Yükleniyor…':'PDF / Görsel / MP4 Dosyası Yükle'}<input type="file" accept=".pdf,image/*,video/mp4,video/webm,text/plain" onChange={upload} disabled={uploading}/></label><small>Maksimum 50 MB. Hassas/kişisel belgeler için public eğitim depolamasını kullanmayın.</small></Panel><Panel title="Ek Sınav Sorusu"><form className="form" onSubmit={addQ}><textarea name="q" placeholder="Soru" required/><input name="a" placeholder="A seçeneği" required/><input name="b" placeholder="B seçeneği" required/><input name="c" placeholder="C seçeneği" required/><input name="d" placeholder="D seçeneği" required/><select name="answer"><option value="0">Doğru: A</option><option value="1">Doğru: B</option><option value="2">Doğru: C</option><option value="3">Doğru: D</option></select><button className="primary">Soruyu Ekle</button></form></Panel></div>}</Modal>}

function Assignments({s,setS,user,role,online,notify,forcedCompany}){const mine=role==='participant'?s.assignments.filter(a=>a.userId===user.id):role==='company_admin'?s.assignments.filter(a=>s.users.find(u=>u.id===a.userId)?.companyId===user.companyId):s.assignments;const[start,setStart]=useState(null),[open,setOpen]=useState(false),[company,setCompany]=useState(forcedCompany||(role==='company_admin'?user.companyId:(s.companies[0]?.id||'')));const participants=s.users.filter(u=>u.role==='participant'&&(role!=='company_admin'||u.companyId===user.companyId)&&u.companyId===company);const add=e=>{e.preventDefault();const f=new FormData(e.currentTarget),userIds=[...f.getAll('users')],courseId=f.get('course'),due=f.get('due');const rows=userIds.filter(uid=>!s.assignments.some(a=>a.userId===uid&&a.courseId===courseId&&a.status!=='completed')).map(userId=>({id:uid('a'),userId,courseId,due,status:'assigned',progress:0,score:null,assignedAt:new Date().toISOString().slice(0,10)}));setS(x=>({...x,assignments:[...x.assignments,...rows]}));setOpen(false);notify(`${rows.length} eğitim ataması oluşturuldu.`)};const complete=(a,score)=>{if(!online){notify('Sınavın sonuçlandırılması ve sertifika üretimi için internet bağlantısı gerekir.');return}if(!s.settings?.certificateApprovals?.[a.userId]){setS(x=>({...x,assignments:x.assignments.map(z=>z.id===a.id?{...z,status:'completed',progress:100,score,completedAt:new Date().toISOString().slice(0,10)}:z)}));setStart(null);notify('Eğitim tamamlandı. Sertifika için Yönetim onayı bekleniyor.');return}const course=s.courses.find(c=>c.id===a.courseId),issued=new Date(),exp=new Date();exp.setMonth(exp.getMonth()+(course.validMonths||12));const cert={id:`${s.settings.certificatePrefix||'ARYA'}-${issued.getFullYear()}-${String(s.certificates.length+1).padStart(5,'0')}`,userId:a.userId,courseId:a.courseId,issuedAt:issued.toISOString().slice(0,10),expiresAt:exp.toISOString().slice(0,10),score,status:'valid'};setS(x=>({...x,assignments:x.assignments.map(z=>z.id===a.id?{...z,status:'completed',progress:100,score,completedAt:issued.toISOString().slice(0,10)}:z),certificates:[...x.certificates,cert]}));if(configured)supabase.from('certificate_registry').upsert({certificate_no:cert.id,holder_name:s.users.find(u=>u.id===a.userId)?.name||'Katılımcı',course_title:course.title,score,issued_at:cert.issuedAt,expires_at:cert.expiresAt,status:'valid',language:'tr'});setStart(null);notify('Eğitim tamamlandı ve sertifika oluşturuldu.')};const remove=a=>{if(!confirm('Bu atamayı iptal etmek istiyor musunuz?'))return;setS(x=>({...x,assignments:x.assignments.filter(z=>z.id!==a.id)}));notify('Atama kaldırıldı.')};return <><div className="toolbar split"><div><b>{mine.length}</b> toplam atama</div>{role!=='participant'&&<button className="primary" onClick={()=>setOpen(true)}>+ Yeni Atama</button>}</div><Panel title="Eğitim Atamaları">{mine.length===0?<Empty title="Henüz eğitim ataması yok" text={role==='participant'?'Size eğitim atandığında burada görünecek.':'Yeni Atama ile firma veya çalışan seçerek eğitimi hemen atayabilirsiniz.'}/>:<div className="table"><div className="tr th"><span>Katılımcı</span><span>Eğitim</span><span>Son Tarih</span><span>Durum</span><span>İlerleme</span><span>İşlem</span></div>{mine.map(a=>{const c=s.courses.find(x=>x.id===a.courseId),u=s.users.find(x=>x.id===a.userId);return <div className="tr" key={a.id}><span>{u?.name||'-'}</span><span><b>{c?.title||'-'}</b></span><span>{fmtDate(a.due)}</span><span><Pill kind={a.status}>{statusLabel[a.status]||a.status}</Pill></span><span>%{a.progress||0}</span><span className="actions">{a.status!=='completed'&&<button onClick={()=>setStart(a)}>Eğitime Gir</button>}{role!=='participant'&&a.status!=='completed'&&<button className="danger mini" onClick={()=>remove(a)}>İptal</button>}</span></div>})}</div>}</Panel>{open&&<Modal title="Yeni Eğitim Ataması" close={()=>setOpen(false)}><form className="form" onSubmit={add}><label>Firma<select value={company} onChange={e=>setCompany(e.target.value)}>{s.companies.filter(c=>role!=='company_admin'||c.id===user.companyId).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Eğitim<select name="course" required>{s.courses.map(c=><option value={c.id} key={c.id}>{c.title}</option>)}</select></label><label>Son Tarih<input type="date" name="due" defaultValue={daysFromNow(s.settings.defaultDueDays||30)} required/></label><label>Katılımcılar<div className="check-list">{participants.length?participants.map(u=><label key={u.id}><input type="checkbox" name="users" value={u.id}/><span>{u.name} <small>• {s.companies.find(c=>c.id===u.companyId)?.name} • {u.employmentType==='contractor'?`Taşeron${u.contractorCompany?' / '+u.contractorCompany:''}`:(u.workforce==='blue'?'Mavi Yaka':'Beyaz Yaka')}</small></span></label>):<span className="muted">Bu filtrede katılımcı bulunamadı.</span>}</div></label><button className="primary">Atamaları Oluştur</button></form></Modal>}{start&&<LearningPlayer assignment={start} s={s} onPass={complete} close={()=>setStart(null)} online={online}/>}</>}
function LearningPlayer({assignment,s,onPass,close,online}){const c=s.courses.find(x=>x.id===assignment.courseId);const lessons=[...(c.modules||[]).map(x=>({...x,kind:'arya'})),...(c.customContents||[]).map(x=>({id:x.id,title:x.title,body:x.body||'',bullets:[],url:x.url,kind:'custom'}))];const[step,setStep]=useState(0),[exam,setExam]=useState(false),[answers,setAnswers]=useState({}),[result,setResult]=useState(null);const qs=examQuestions(c);const finish=()=>{if(!online){setResult({offline:true});return}if(Object.keys(answers).length<qs.length){setResult({missing:true});return}const score=Math.round(qs.filter(q=>Number(answers[q.id])===q.answer).length*100/(qs.length||1));setResult({score,passed:score>=c.passing});if(score>=c.passing)onPass(assignment,score)};const l=lessons[step];return <Modal title={c.title} close={close} wide>{!exam?<div className="learning-player"><div className="progress"><i style={{width:`${Math.round((step+1)/(lessons.length||1)*100)}%`}}/></div>{l?<article className={`lesson ${l.kind==='custom'?'custom':''}`}><span>BÖLÜM {step+1}/{lessons.length} {l.kind==='custom'?'• KURUMSAL EK İÇERİK':''}</span><h2>{l.title}</h2>{l.body&&<p>{l.body}</p>}{l.bullets?.length>0&&<ul>{l.bullets.map(x=><li key={x}>{x}</li>)}</ul>}{l.url&&<a className="content-link" href={l.url} target="_blank" rel="noreferrer">Ek İçeriği Aç</a>}</article>:<Empty title="İçerik bulunamadı" text="Bu eğitim için ders içeriği tanımlanmamış."/>}{step<lessons.length-1?<button className="primary" onClick={()=>setStep(step+1)}>Sonraki Bölüm</button>:<button className="primary" onClick={()=>setExam(true)}>Sınava Geç</button>}</div>:<div className="exam">{!result&&<>{qs.map((q,i)=><div className="exam-q" key={q.id}><b>{i+1}. {q.text}</b>{q.options.map((o,j)=><label key={o}><input type="radio" name={q.id} value={j} checked={String(answers[q.id])===String(j)} onChange={()=>setAnswers(prev=>({...prev,[q.id]:j}))}/><span>{o}</span></label>)}</div>)}<button className="primary" onClick={finish}>Sınavı Bitir</button></>}{result?.missing&&<div className="notice">Lütfen tüm soruları cevaplayın.<br/><button onClick={()=>setResult(null)}>Sınava Dön</button></div>}{result?.offline&&<div className="notice">Sınav sonucu çevrimiçi doğrulanır. İnternet bağlantısı geldikten sonra tekrar bitirin.</div>}{result&&!result.offline&&!result.missing&&!result.passed&&<div className="result bad"><h2>%{result.score}</h2><p>Geçme puanı %{c.passing}. Eğitimi gözden geçirip tekrar deneyebilirsiniz.</p><button onClick={()=>setResult(null)}>Tekrar Dene</button></div>}</div>}</Modal>}
function Matrix({s,role,user,forcedCompany}){const[company,setCompany]=useState(forcedCompany||(role==='company_admin'?user.companyId:(s.companies[0]?.id||'')));const firms=s.companies.filter(c=>role!=='company_admin'||c.id===user.companyId);const participants=s.users.filter(u=>u.role==='participant'&&u.companyId===company),courses=s.courses.filter(c=>c.mandatory).slice(0,8);return <><div className="toolbar"><label>Katılımcı Firma<select value={company} onChange={e=>setCompany(e.target.value)}>{firms.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label></div><Panel title="Çevre Yetkinlik Matrisi"><div className="matrix"><div className="matrix-row head"><b>Personel</b>{courses.map(c=><span title={c.title} key={c.id}>{c.title.slice(0,12)}</span>)}</div>{participants.map(u=><div className="matrix-row" key={u.id}><b>{u.name}<small>{u.employmentType==='contractor'?`Taşeron${u.contractorCompany?' • '+u.contractorCompany:''}`:''}</small></b>{courses.map(c=>{const a=s.assignments.find(x=>x.userId===u.id&&x.courseId===c.id);return <span className={`matrix-state ${a?.status==='completed'?'ok':a?.status==='overdue'?'bad':a?'warn':'none'}`} key={c.id}>{a?.status==='completed'?'✓':a?'•':'—'}</span>})}</div>)}</div></Panel></>}
function Certificates({s,setS,user,role,notify,forcedCompany}){const[sel,setSel]=useState(null),[search,setSearch]=useState(''),[company,setCompany]=useState(forcedCompany||(role==='company_admin'?user.companyId:(s.companies[0]?.id||'')));useEffect(()=>{if(forcedCompany)setCompany(forcedCompany)},[forcedCompany]);const approved=s.settings?.certificateApprovals||{};const list=(s.certificates||[]).filter(c=>{const u=s.users.find(x=>x.id===c.userId);return role==='participant'?c.userId===user.id:u?.companyId===company}).filter(c=>{const u=s.users.find(x=>x.id===c.userId),course=s.courses.find(x=>x.id===c.courseId);return `${u?.name||''} ${course?.title||''} ${c.id}`.toLowerCase().includes(search.toLowerCase())});const revoke=async c=>{if(!confirm('Sertifika iptal edilsin mi?'))return;setS(x=>({...x,certificates:x.certificates.map(z=>z.id===c.id?{...z,status:'revoked'}:z)}));if(configured)await supabase.from('certificate_registry').update({status:'revoked'}).eq('certificate_no',c.id);notify('Sertifika iptal edildi.')};return <><div className="toolbar split">{role!=='participant'&&!forcedCompany&&<label>Katılımcı Firma<select value={company} onChange={e=>setCompany(e.target.value)}>{s.companies.filter(c=>role!=='company_admin'||c.id===user.companyId).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>}<input className="search" placeholder="Ad, eğitim veya sertifika no ara" value={search} onChange={e=>setSearch(e.target.value)}/><span><b>{list.length}</b> sertifika</span></div>{list.length===0?<Empty title="Henüz sertifika oluşmadı" text="Onaylı katılımcı eğitimini tamamlayıp sınavdan geçtiğinde sertifika burada oluşur."/>:<div className="cert-grid">{list.map(c=>{const u=s.users.find(x=>x.id===c.userId),course=s.courses.find(x=>x.id===c.courseId),firm=s.companies.find(x=>x.id===u?.companyId);return <div className="cert-card" key={c.id}><span>{c.status==='revoked'?'İPTAL EDİLDİ':'SERTİFİKA / CERTIFICATE'}</span><h3>{course?.title||'Eğitim'}</h3><p>{u?.name||'Katılımcı'}</p><small>{firm?.name||'-'}</small><small>{c.id} • {fmtDate(c.issuedAt)} • Son: {fmtDate(c.expiresAt)}</small><div className="actions">{role==='participant'||approved[c.userId]?<button onClick={()=>setSel(c)}>TR / EN Sertifika</button>:<span className="muted">Yönetim onayı bekliyor</span>}{role!=='participant'&&c.status!=='revoked'&&<button className="danger mini" onClick={()=>revoke(c)}>İptal</button>}</div></div>})}</div>}{sel&&<CertificateModal c={sel} s={s} close={()=>setSel(null)}/>}</>}
function CertificateModal({c,s,close}){const[lang,setLang]=useState('tr'),[qr,setQr]=useState('');const u=s.users.find(x=>x.id===c.userId)||{name:'Katılımcı'},course=s.courses.find(x=>x.id===c.courseId)||{title:'Eğitim',titleEn:'Training',duration:'-'},firm=s.companies.find(x=>x.id===u.companyId);useEffect(()=>{let alive=true;Promise.resolve(QRCode.toDataURL(`${location.origin}/?verify=${encodeURIComponent(c.id)}`,{width:240,margin:1})).then(v=>alive&&setQr(v)).catch(()=>alive&&setQr(''));return()=>{alive=false}},[c.id]);const tr=lang==='tr';const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const printPdf=()=>{const w=window.open('','_blank','width=1200,height=850');if(!w)return;const title=tr?(s.settings.certificateTitle||'BAŞARI SERTİFİKASI'):'CERTIFICATE OF COMPLETION';w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(c.id)}</title><style>@page{size:A4 landscape;margin:0}*{box-sizing:border-box}body{margin:0;padding:9mm;font-family:Arial;color:#173024}.sheet{width:279mm;height:192mm;border:2mm double #264f34;padding:10mm 15mm;text-align:center;position:relative}.logo{width:38mm}.name{font:28pt Georgia;margin:8mm 0 2mm}.firm{font-size:12pt;color:#52675a;margin-bottom:7mm}.info{display:grid;grid-template-columns:repeat(5,1fr);gap:3mm;margin:8mm auto;width:240mm}.info div{background:#f3f7f2;padding:3mm}.qr{width:24mm}.note{position:absolute;right:16mm;bottom:18mm;max-width:85mm;text-align:right;font-size:8pt}.sign{position:absolute;right:16mm;bottom:10mm}.no{position:fixed;right:10px;top:10px}@media print{.no{display:none}}</style></head><body><button class="no" onclick="window.print()">PDF / Yazdır</button><div class="sheet"><img class="logo" src="${location.origin}/arya-logo.png"><h1>${esc(title)}</h1><p>${tr?'Bu belge':'This is to certify that'}</p><div class="name">${esc(u.name)}</div><div class="firm">${esc(firm?.name||'')}</div><p><b>${esc(tr?course.title:(course.titleEn||course.title))}</b> ${tr?'eğitimini başarıyla tamamlamıştır.':'training has been successfully completed.'}</p><div class="info"><div>Sertifika No<br><b>${esc(c.id)}</b></div><div>Puan<br><b>%${esc(c.score)}</b></div><div>Süre<br><b>${esc(course.duration)} dk</b></div><div>Düzenlenme<br><b>${esc(fmtDate(c.issuedAt))}</b></div><div>Geçerlilik<br><b>${esc(fmtDate(c.expiresAt))}</b></div></div>${qr?`<img class="qr" src="${qr}">`:''}${s.settings.certificateNote?`<div class="note">${esc(s.settings.certificateNote)}</div>`:''}<div class="sign">${esc(s.settings.certificateSigner||'ARYA Akademi')}</div></div></body></html>`);w.document.close()};return <Modal title="A4 Sertifika Önizleme" close={close} wide><div className="certificate-toolbar"><button className={tr?'primary':''} onClick={()=>setLang('tr')}>Türkçe</button><button className={!tr?'primary':''} onClick={()=>setLang('en')}>English</button><button onClick={printPdf}>A4 PDF / Yazdır</button></div><div className="certificate a4-landscape"><img className="cert-logo" src="/arya-logo.png"/><div className="cert-brand">ARYA AKADEMİ</div><span>{tr?(s.settings.certificateTitle||'BAŞARI SERTİFİKASI'):'CERTIFICATE OF COMPLETION'}</span><p>{tr?'Bu belge':'This is to certify that'}</p><h1>{u.name}</h1><h3>{firm?.name||''}</h3><p><b>{tr?course.title:(course.titleEn||course.title)}</b> {tr?'eğitimini başarıyla tamamlamıştır.':'training has been successfully completed.'}</p><div className="cert-info"><div><small>Sertifika No</small><b>{c.id}</b></div><div><small>Başarı</small><b>%{c.score}</b></div><div><small>Süre</small><b>{course.duration} dk</b></div><div><small>Düzenlenme</small><b>{fmtDate(c.issuedAt)}</b></div><div><small>Geçerlilik</small><b>{fmtDate(c.expiresAt)}</b></div></div>{qr&&<img className="qr" src={qr}/>}<small className="verify-text">QR kod ile doğrulanabilir.</small>{s.settings.certificateNote&&<small className="cert-note">{s.settings.certificateNote}</small>}<small className="cert-signer">{s.settings.certificateSigner||'ARYA Akademi'}</small></div></Modal>}
function Reports({s,role,user}){const assignments=role==='company_admin'?s.assignments.filter(a=>s.users.find(u=>u.id===a.userId)?.companyId===user.companyId):s.assignments;const mobileAccess=role==='company_admin'?(s.mobileAccess||[]).filter(m=>m.companyId===user.companyId):(s.mobileAccess||[]);const certificates=role==='company_admin'?s.certificates.filter(c=>s.users.find(u=>u.id===c.userId)?.companyId===user.companyId):s.certificates;const all=[...assignments,...mobileAccess.map(m=>({status:m.status,score:m.score}))],done=all.filter(x=>x.status==='completed').length,late=all.filter(x=>x.status==='overdue'||x.status==='expired').length;const csv=()=>{const rows=[['Personel','Personel Türü','Taşeron Firma','Eğitim','Kanal','Durum','Puan','Son Tarih'],...assignments.map(a=>{const u=s.users.find(x=>x.id===a.userId);return [u?.name,u?.employmentType==='contractor'?'Taşeron Çalışan':'Müşteri Çalışanı',u?.contractorCompany||'',s.courses.find(c=>c.id===a.courseId)?.title,'Portal',statusLabel[a.status],a.score??'',a.due]}),...mobileAccess.map(m=>{const u=s.users.find(x=>x.name===m.employeeName&&x.companyId===m.companyId);return [m.employeeName,u?.employmentType==='contractor'?'Taşeron Çalışan':'Müşteri Çalışanı',u?.contractorCompany||'',s.courses.find(c=>c.id===m.courseId)?.title,'Mobil',statusLabel[m.status]||m.status,m.score??'',m.due]})];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(';')).join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='arya-akademi-v2-4-2-rapor.csv';a.click()};return <><div className="stats"><Card n={all.length} t="Toplam Atama"/><Card n={`%${Math.round(done/(all.length||1)*100)}`} t="Tamamlama"/><Card n={late} t="Geciken / Süresi Dolan"/><Card n={certificates.length+mobileAccess.filter(x=>x.certificateNo).length} t="Sertifika"/></div><Panel title="Portal + Mobil Rapor"><p>Beyaz yaka portal atamalarını ve mavi yaka mobil katılımları aynı raporda dışa aktarın.</p><button className="primary" onClick={csv}>CSV Raporu İndir</button></Panel></>}
function Announcements({s}){return <Panel title="Duyuru ve Bilgi Merkezi">{s.announcements.map(n=><div className="announce big" key={n.id}><b>{n.title}</b><p>{n.text}</p><small>{fmtDate(n.date)}</small></div>)}</Panel>}

function MobileAdmin({s,setS,online,notify,role,user,forcedCompany}){const[open,setOpen]=useState(false),[qrItem,setQrItem]=useState(null),[groupQr,setGroupQr]=useState(false);const allowedUsers=s.users.filter(u=>u.role==='participant'&&(forcedCompany?u.companyId===forcedCompany:(role!=='company_admin'||u.companyId===user.companyId)));const allowedMobile=(s.mobileAccess||[]).filter(m=>forcedCompany?m.companyId===forcedCompany:(role!=='company_admin'||m.companyId===user.companyId));const create=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),user=s.users.find(u=>u.id===f.get('user')),courseId=f.get('course'),due=f.get('due'),pin=f.get('pin')||String(user.employeeNo||'').slice(-4)||String(user.phone||'').slice(-4);if(!pin||pin.length<4){notify('En az 4 karakterlik PIN girin.');return}let token=uid('demo').replaceAll('_','');let id=uid('m');if(configured){if(!online){notify('Mobil bağlantı oluşturmak için internet gerekir.');return}const {data,error}=await supabase.rpc('create_mobile_access',{p_employee_name:user.name,p_employee_no:user.employeeNo||'',p_phone:onlyDigits(user.phone),p_company_id:user.companyId||'',p_course_id:courseId,p_due:due,p_pin:pin,p_days:Number(f.get('days')||30)});if(error){notify('V2 migration gerekli: '+error.message);return}token=data;id=uid('m')}const item={id,token,employeeName:user.name,employeeNo:user.employeeNo||'',phone:onlyDigits(user.phone),companyId:user.companyId,courseId,due,expiresAt:daysFromNow(Number(f.get('days')||30)),status:'assigned',progress:0,score:null};setS(x=>({...x,mobileAccess:[item,...(x.mobileAccess||[])]}));setOpen(false);notify('Kişisel mobil eğitim bağlantısı oluşturuldu.')};const link=m=>`${location.origin}/?join=${m.token}`;const whatsapp=m=>{const phone=onlyDigits(m.phone);const course=s.courses.find(c=>c.id===m.courseId);const text=`Merhaba ${m.employeeName}, ARYA Akademi üzerinden size ${course?.title} eğitimi atanmıştır. Eğitime katılmak için: ${link(m)} Son tarih: ${fmtDate(m.due)}`;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(text)}`,'_blank')};return <><div className="toolbar"><button className="primary" onClick={()=>setOpen(true)}>+ Mobil Eğitim Linki</button><button className="button-link" onClick={()=>setGroupQr(true)}>Toplu / Kiosk QR</button><a className="button-link" href="/?kiosk=1" target="_blank">Kiosk Modunu Aç</a></div><Panel title="Mavi Yaka / Mobil Katılım"><div className="table mobile-table"><div className="tr th"><span>Personel</span><span>Eğitim</span><span>Durum</span><span>Son Tarih</span><span>Katılım</span><span>Gönder</span></div>{allowedMobile.map(m=><div className="tr" key={m.token}><span><b>{m.employeeName}</b><small>{m.employeeNo}</small></span><span>{s.courses.find(c=>c.id===m.courseId)?.title}</span><span><Pill kind={m.status}>{statusLabel[m.status]||m.status}</Pill></span><span>{fmtDate(m.due)}</span><span>%{m.progress||0}{m.score!=null&&` • Puan ${m.score}`}</span><span className="actions"><button onClick={()=>navigator.clipboard?.writeText(link(m)).then(()=>notify('Link kopyalandı.'))}>Link</button><button onClick={()=>setQrItem(m)}>QR</button>{m.phone&&<button onClick={()=>whatsapp(m)}>WhatsApp</button>}</span></div>)}</div></Panel>{open&&<Modal title="Kişisel Mobil Eğitim Linki" close={()=>setOpen(false)}><form className="form" onSubmit={create}><label>Personel<select name="user" required>{allowedUsers.map(u=><option key={u.id} value={u.id}>{u.name} • {u.employmentType==='contractor'?`Taşeron${u.contractorCompany?' / '+u.contractorCompany:''}`:(u.workforce==='blue'?'Mavi Yaka':'Beyaz Yaka')}</option>)}</select></label><label>Eğitim<select name="course">{s.courses.map(c=><option value={c.id} key={c.id}>{c.title}</option>)}</select></label><label>Son Tarih<input type="date" name="due" defaultValue={daysFromNow(14)} required/></label><label>Link Süresi<select name="days"><option value="7">7 gün</option><option value="30">30 gün</option><option value="60">60 gün</option><option value="90">90 gün</option></select></label><label>Doğrulama PIN'i<input name="pin" placeholder="Örn. telefonun son 4 hanesi" minLength="4" required/></label><button className="primary">Bağlantı Oluştur</button></form></Modal>}{qrItem&&<QrModal item={qrItem} link={link(qrItem)} close={()=>setQrItem(null)}/>} {groupQr&&<QrModal item={{employeeName:'Toplu Katılım / Kiosk'}} link={`${location.origin}/?kiosk=1`} close={()=>setGroupQr(false)}/>}</>}
function QrModal({item,link,close}){const[qr,setQr]=useState('');useEffect(()=>{QRCode.toDataURL(link,{width:320,margin:2}).then(setQr)},[link]);return <Modal title="Eğitim QR Kodu" close={close}><div className="qr-modal"><h3>{item.employeeName}</h3>{qr&&<img src={qr}/>}<p>Çalışan QR kodu telefonuyla okutarak kişisel eğitim ekranına geçer.</p><button onClick={()=>navigator.clipboard?.writeText(link)}>Linki Kopyala</button></div></Modal>}

function normHeader(v){return String(v||'').toLocaleLowerCase('tr-TR').replace(/[ıİ]/g,'i').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
function cellValue(row,names){const wanted=names.map(normHeader);for(const [k,v] of Object.entries(row||{}))if(wanted.includes(normHeader(k)))return String(v??'').trim();return ''}
function normalizeWorkforce(v,def='white'){const x=String(v||'').toLocaleLowerCase('tr-TR');return x.includes('mavi')||x==='blue'?'blue':x.includes('beyaz')||x==='white'?'white':def}
function normalizeRole(v){const x=String(v||'').toLocaleLowerCase('tr-TR');return x.includes('firma')||x.includes('yonetici')||x.includes('yönetici')||x==='company_admin'?'company_admin':'participant'}
function findCompanyId(s,name,fallback=''){const q=String(name||'').trim().toLocaleLowerCase('tr-TR');if(!q)return fallback;const c=s.companies.find(x=>String(x.name||'').trim().toLocaleLowerCase('tr-TR')===q);return c?.id||''}
async function readWorkbookFile(file){const buf=await file.arrayBuffer();const wb=XLSX.read(buf,{type:'array',cellDates:false});const ws=wb.Sheets[wb.SheetNames[0]];return XLSX.utils.sheet_to_json(ws,{defval:'',raw:false})}
function BulkImportModal({kind,s,setS,role,user,selectedCompany,close,notify}){const[rows,setRows]=useState([]),[fileName,setFileName]=useState(''),[busy,setBusy]=useState(false);const isContractor=kind==='contractor';const allowedCompany=role==='company_admin'?user.companyId:(selectedCompany!=='all'?selectedCompany:'');const template=isContractor?'/taseron_calisan_toplu_yukleme_sablonu.xlsx':'/calisan_toplu_yukleme_sablonu.xlsx';
 const parse=async e=>{const file=e.target.files?.[0];if(!file)return;setBusy(true);try{const raw=await readWorkbookFile(file);const seen=new Set();const parsed=raw.map((r,i)=>{const companyName=cellValue(r,['Müşteri','Musteri','Firma','Müşteri Firma']);const companyId=findCompanyId(s,companyName,allowedCompany);const name=cellValue(r,['Ad Soyad','AdSoyad','Ad','Çalışan','Calisan']);const employeeNo=cellValue(r,['Sicil No','Sicil','Personel No','PersonelNo']);const email=cellValue(r,['E-posta','Eposta','Email']);const phone=onlyDigits(cellValue(r,['Telefon','Cep Telefonu','CepTelefonu']));const contractorCompany=isContractor?cellValue(r,['Taşeron Firma','Taseron Firma','TaşeronFirma','TaseronFirma']):'';const workforce=normalizeWorkforce(cellValue(r,['Yaka','Çalışan Türü','Calisan Turu']),isContractor?'blue':'white');const row={id:uid('u'),name,email,role:isContractor?'participant':normalizeRole(cellValue(r,['Yetki','Rol'])),companyId,department:cellValue(r,['Departman','Bölüm','Bolum','Saha']),title:cellValue(r,['Görev','Gorev','Unvan']),phone,employeeNo,workforce,employmentType:isContractor?'contractor':'employee',contractorCompany,active:true};const errs=[];if(!name)errs.push('Ad Soyad boş');if(!companyId)errs.push(companyName?`Müşteri bulunamadı: ${companyName}`:'Müşteri boş');if(isContractor&&!contractorCompany)errs.push('Taşeron Firma boş');const dupKey=`${companyId}|${employeeNo||email||phone||name.toLocaleLowerCase('tr-TR')}|${isContractor?contractorCompany.toLocaleLowerCase('tr-TR'):''}`;const existing=s.users.some(u=>u.companyId===companyId&&u.employmentType===(isContractor?'contractor':'employee')&&((employeeNo&&u.employeeNo===employeeNo)||(email&&u.email&&u.email.toLocaleLowerCase()===email.toLocaleLowerCase())||(phone&&u.phone===phone)));if(existing||seen.has(dupKey))errs.push(existing?'Sistemde mükerrer kayıt':'Excel içinde mükerrer kayıt');seen.add(dupKey);return{line:i+2,row,errors:errs}});setRows(parsed);setFileName(file.name)}catch(err){notify('Excel okunamadı: '+err.message);setRows([])}finally{setBusy(false);e.target.value=''}};
 const valid=rows.filter(x=>x.errors.length===0);const invalid=rows.filter(x=>x.errors.length>0);const commit=()=>{if(!valid.length){notify('Yüklenecek geçerli satır bulunamadı.');return}setS(x=>({...x,users:[...x.users,...valid.map(v=>v.row)]}));notify(`${valid.length} ${isContractor?'taşeron çalışan':'çalışan'} Excel'den yüklendi.${invalid.length?` ${invalid.length} hatalı/mükerrer satır atlandı.`:''}`);close()};return <Modal title={`${isContractor?'Taşeron Çalışanlar':'Çalışanlar'} • Excel Toplu Yükleme`} close={close} wide><div className="bulk-import"><div className="fixed-note">Excel şablonunu indirin, kolon adlarını değiştirmeden doldurun. Sistem müşteri, zorunlu alan ve mükerrer kayıt kontrolü yapar. {role==='company_admin'?'Müşteri alanı boş bırakılırsa kendi firmanız kullanılır.':selectedCompany!=='all'?'Müşteri alanı boş bırakılırsa seçili müşteri kullanılır.':'Tüm firmalar görünümünde Müşteri sütunu zorunludur.'}</div><div className="toolbar split"><a className="button-link" href={template} download>Excel Şablonunu İndir</a><label className="primary file-button">{busy?'Okunuyor…':'Excel Dosyası Seç'}<input type="file" accept=".xlsx,.xls,.csv" onChange={parse} disabled={busy}/></label></div>{fileName&&<p className="muted">Dosya: <b>{fileName}</b></p>}{rows.length>0&&<><div className="stats bulk-stats"><Card n={rows.length} t="Toplam Satır"/><Card n={valid.length} t="Yüklemeye Hazır"/><Card n={invalid.length} t="Hatalı / Mükerrer"/></div><div className="table bulk-table"><div className="tr th"><span>Satır</span><span>Ad Soyad</span><span>Müşteri</span><span>{isContractor?'Taşeron Firma':'Yaka'}</span><span>Sicil</span><span>Kontrol</span></div>{rows.slice(0,200).map(x=><div className={`tr ${x.errors.length?'import-error':''}`} key={x.line}><span>{x.line}</span><span><b>{x.row.name||'-'}</b></span><span>{s.companies.find(c=>c.id===x.row.companyId)?.name||'-'}</span><span>{isContractor?(x.row.contractorCompany||'-'):(x.row.workforce==='blue'?'Mavi Yaka':'Beyaz Yaka')}</span><span>{x.row.employeeNo||'-'}</span><span>{x.errors.length?<small>{x.errors.join(' • ')}</small>:<Pill kind="completed">Hazır</Pill>}</span></div>)}</div>{rows.length>200&&<p className="muted">Önizlemede ilk 200 satır gösteriliyor. Tüm geçerli satırlar yüklemeye dahil edilir.</p>}<div className="actions"><button className="primary" onClick={commit} disabled={!valid.length}>Geçerli {valid.length} Satırı Yükle</button><button onClick={close}>Vazgeç</button></div></>}</div></Modal>}

