function Instructors({s,setS,notify}){const[open,setOpen]=useState(false),[edit,setEdit]=useState(null);const save=e=>{e.preventDefault();const f=new FormData(e.currentTarget),row={id:edit?.id||uid('i'),name:f.get('name'),speciality:f.get('speciality'),email:f.get('email'),phone:f.get('phone'),tc:f.get('tc'),diplomaNo:f.get('diplomaNo'),diplomaInstitution:f.get('diplomaInstitution'),certificateName:f.get('certificateName'),certificateNo:f.get('certificateNo'),certificateInstitution:f.get('certificateInstitution'),active:true};setS(x=>({...x,instructors:edit?x.instructors.map(i=>i.id===edit.id?row:i):[...x.instructors,row]}));setOpen(false);setEdit(null);notify('Eğitmen kaydedildi.')};return <><div className="toolbar"><button className="primary" onClick={()=>{setEdit(null);setOpen(true)}}>+ Eğitmen Ekle</button></div><div className="company-grid">{s.instructors.map(i=><div className="company" key={i.id}><b>{i.name}</b><span>{i.speciality}</span><small>{i.email}</small><small>Diploma: {i.diplomaNo||'-'} • Sertifika: {i.certificateNo||'-'}</small><button onClick={()=>{setEdit(i);setOpen(true)}}>Düzenle</button></div>)}</div>{open&&<Modal title={edit?'Eğitmen Düzenle':'Yeni Eğitmen'} close={()=>setOpen(false)}><form className="form" onSubmit={save}><h4>Temel Bilgiler</h4><input name="name" placeholder="Ad Soyad" defaultValue={edit?.name||''} required/><input name="tc" placeholder="T.C. Kimlik No" maxLength="11" defaultValue={edit?.tc||''}/><input name="speciality" placeholder="Uzmanlık / Unvan" defaultValue={edit?.speciality||''}/><input name="email" type="email" placeholder="E-posta" defaultValue={edit?.email||''}/><input name="phone" placeholder="Telefon" defaultValue={edit?.phone||''}/><h4>Diploma Bilgileri</h4><input name="diplomaNo" placeholder="Diploma No" defaultValue={edit?.diplomaNo||''}/><input name="diplomaInstitution" placeholder="Diploma Alınan Kurum / Üniversite" defaultValue={edit?.diplomaInstitution||''}/><h4>Sertifika / Yeterlilik</h4><input name="certificateName" placeholder="Sertifika / Yeterlilik Adı" defaultValue={edit?.certificateName||''}/><input name="certificateNo" placeholder="Sertifika No" defaultValue={edit?.certificateNo||''}/><input name="certificateInstitution" placeholder="Sertifikanın Alındığı Kurum" defaultValue={edit?.certificateInstitution||''}/><button className="primary">Kaydet</button></form></Modal>}</>}
function KnowledgeBaseViewer({s,user,role}){const[topic,setTopic]=useState('all');const blogs=s.settings.blogs||[],topics=s.settings.blogTopics||[];const visible=blogs.filter(b=>b.published!==false&&(role==='system_admin'||!b.companyIds?.length||b.companyIds.includes(user.companyId))).filter(b=>topic==='all'||b.topicId===topic);return <><div className="toolbar"><label>Konu<select value={topic} onChange={e=>setTopic(e.target.value)}><option value="all">Tüm Konular</option>{topics.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><span><b>{visible.length}</b> yayın</span></div>{visible.length?<div className="knowledge-list">{visible.map(b=><article className="knowledge-card" key={b.id}><span>{topics.find(t=>t.id===b.topicId)?.name||'Bilgi Bankası'}</span><h3>{b.title}</h3><p>{b.body}</p><small>{fmtDate(b.date)}</small></article>)}</div>:<Empty title="Henüz yayınlanmış içerik yok" text="Yönetim > Bilgi Bankası bölümünden içerik yayınlanabilir."/>}</>}
function KnowledgeBaseAdmin({s,setS,notify}){const topics=s.settings.blogTopics||[],blogs=s.settings.blogs||[];const addTopic=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=f.get('topic')?.trim();if(!name)return;setS(x=>({...x,settings:{...x.settings,blogTopics:[...(x.settings.blogTopics||[]),{id:uid('bt'),name}]}}));e.currentTarget.reset();notify('Bilgi Bankası konusu eklendi.')};const addBlog=e=>{e.preventDefault();const f=new FormData(e.currentTarget);setS(x=>({...x,settings:{...x.settings,blogs:[...(x.settings.blogs||[]),{id:uid('blog'),topicId:f.get('topicId'),title:f.get('title'),body:f.get('body'),companyIds:f.get('scope')==='general'?[]:f.getAll('companyIds'),published:true,date:new Date().toISOString().slice(0,10)}]}}));e.currentTarget.reset();notify('Bilgi Bankası yazısı yayınlandı.')};const toggle=id=>setS(x=>({...x,settings:{...x.settings,blogs:(x.settings.blogs||[]).map(b=>b.id===id?{...b,published:b.published===false?true:false}:b)}}));return <><div className="grid2"><Panel title="Konu Yönetimi"><form className="form" onSubmit={addTopic}><input name="topic" placeholder="Yeni konu / kategori" required/><button className="primary">Konu Ekle</button></form></Panel><Panel title="İçerik Hazırla"><form className="form" onSubmit={addBlog}><select name="topicId" required><option value="">Konu seçin</option>{topics.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><input name="title" placeholder="Makale başlığı" required/><textarea name="body" rows="8" placeholder="Makale içeriği" required/><select name="scope"><option value="general">Genel - herkes</option><option value="company">Katılımcı firmalara özel</option></select><div className="check-grid">{s.companies.map(c=><label key={c.id}><input type="checkbox" name="companyIds" value={c.id}/>{c.name}</label>)}</div><button className="primary">Yayınla</button></form></Panel></div><Panel title="Yayınlar">{blogs.map(b=><div className="announce big" key={b.id}><b>{b.title}</b><p>{b.body}</p><small>{b.published===false?'Taslak / gizli':'Yayında'} • {fmtDate(b.date)}</small><button onClick={()=>toggle(b.id)}>{b.published===false?'Yayınla':'Yayından Kaldır'}</button></div>)}</Panel></>}
function Blog(p){return <KnowledgeBaseViewer {...p}/>}
function Management({s,setS,notify,role,user}){const[tab,setTab]=useState('access'),[company,setCompany]=useState(role==='company_admin'?user.companyId:(s.companies[0]?.id||''));const allowed=role==='company_admin'?s.companies.filter(c=>c.id===user.companyId):s.companies;const prices=s.settings.coursePrices||{};const savePrices=e=>{e.preventDefault();const f=new FormData(e.currentTarget),coursePrices={...prices};s.courses.forEach(c=>coursePrices[c.id]=Math.max(0,Number(f.get(`price_${c.id}`)||0)));setS(x=>({...x,settings:{...x.settings,coursePrices}}));notify('Eğitim fiyatları kaydedildi.')};const addAnnouncement=e=>{e.preventDefault();const f=new FormData(e.currentTarget);setS(x=>({...x,announcements:[...(x.announcements||[]),{id:uid('n'),title:f.get('title'),text:f.get('text'),date:new Date().toISOString().slice(0,10),companyIds:f.get('scope')==='general'?[]:f.getAll('companyIds')}]}));e.currentTarget.reset();notify('Duyuru yayınlandı.')};const toggleCertificateApproval=u=>{const approving=!s.settings?.certificateApprovals?.[u.id];setS(x=>{const approvals={...(x.settings.certificateApprovals||{}),[u.id]:approving};let certificates=[...x.certificates];if(approving){for(const a of x.assignments.filter(a=>a.userId===u.id&&a.status==='completed')){if(certificates.some(c=>c.userId===u.id&&c.courseId===a.courseId))continue;const course=x.courses.find(c=>c.id===a.courseId);if(!course)continue;const issued=new Date(a.completedAt||new Date()),exp=new Date(issued);exp.setMonth(exp.getMonth()+(course.validMonths||12));certificates.push({id:`${x.settings.certificatePrefix||'ARYA'}-${issued.getFullYear()}-${String(certificates.length+1).padStart(5,'0')}`,userId:u.id,courseId:a.courseId,issuedAt:issued.toISOString().slice(0,10),expiresAt:exp.toISOString().slice(0,10),score:a.score??0,status:'valid'})}}return {...x,certificates,settings:{...x.settings,certificateApprovals:approvals}}});notify(approving?'Katılımcı onaylandı; tamamlanmış eğitimler için sertifikalar düzenlendi.':'Sertifika düzenleme onayı kaldırıldı.')};const cards=[['access','Kullanıcı Atamaları'],['certificate','Sertifika Yönetimi'],['knowledge','Bilgi Bankası'],['announcements','Duyurular'],['messages','Mesajlar'],['pricing','Fiyatlandırma'],['reports','Raporlar'],['instructors','Eğitmenler'],['kvkk','KVKK Kayıtları']];return <><div className="management-home">{cards.map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}><b>{label}</b><small>Yönet</small></button>)}</div>{tab==='access'&&<AccessControl s={s} setS={setS} notify={notify}/>} {tab==='certificate'&&<Panel title="Sertifika Yönetimi / Onayları"><div className="permission-list">{s.users.filter(u=>u.role==='participant').map(u=><div className="permission-card" key={u.id}><b>{u.name}</b><small>{s.companies.find(c=>c.id===u.companyId)?.name||'-'}</small><button className={s.settings?.certificateApprovals?.[u.id]?'primary small':'small'} onClick={()=>toggleCertificateApproval(u)}>{s.settings?.certificateApprovals?.[u.id]?'Onaylı • Sertifika Düzenlenebilir':'Onay Ver'}</button></div>)}</div></Panel>} {tab==='knowledge'&&<KnowledgeBaseAdmin s={s} setS={setS} notify={notify}/>} {tab==='announcements'&&<Panel title="Duyuru Yönetimi"><form className="form" onSubmit={addAnnouncement}><input name="title" placeholder="Duyuru başlığı" required/><textarea name="text" rows="3" placeholder="Duyuru metni" required/><select name="scope"><option value="general">Genel</option><option value="company">Katılımcı firmalara özel</option></select><div className="check-grid">{s.companies.map(c=><label key={c.id}><input type="checkbox" name="companyIds" value={c.id}/>{c.name}</label>)}</div><button className="primary">Duyuruyu Yayınla</button></form></Panel>} {tab==='messages'&&<Panel title="Mesajlar">{(s.settings.managementMessages||[]).length?(s.settings.managementMessages||[]).slice().reverse().map(m=><div className="announce big" key={m.id}><b>{m.userName}</b><p>{m.text}</p><small>{fmtDate(m.date)}</small></div>):<p className="muted">Henüz mesaj yok.</p>}</Panel>} {tab==='pricing'&&<><Panel title="Fiyatlandırma"><form className="price-list" onSubmit={savePrices}>{s.courses.map(c=><label className="price-row" key={c.id}><span><b>{c.title}</b><small>{c.duration} dk • Geçme %{c.passing}</small></span><span className="price-input"><input name={`price_${c.id}`} type="number" min="0" step="0.01" defaultValue={prices[c.id]||0}/><em>TL / kişi</em></span></label>)}<button className="primary">Fiyatları Kaydet</button></form></Panel><Panel title="Firma Fiyat Özeti"><label>Firma<select value={company} onChange={e=>setCompany(e.target.value)}>{allowed.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label></Panel></>} {tab==='reports'&&<Reports s={s} role={role} user={user}/>} {tab==='instructors'&&<Instructors s={s} setS={setS} notify={notify}/>} {tab==='kvkk'&&<KvkkAudit s={s}/>}</>}
function KvkkConsentGate({s,setS,user,notify}){const[notice,setNotice]=useState(false),[explicitConsent,setExplicitConsent]=useState(false),[busy,setBusy]=useState(false);const accept=async()=>{if(!notice)return;setBusy(true);const version='KVKK-2026-08-v1',at=new Date().toISOString();let evidence={id:uid('kvkk'),userId:user.id,companyId:user.companyId,version,acceptedAt:at,noticeAccepted:true,explicitConsent,channel:'local-demo'};if(configured&&isOnline()){try{const {data,error}=await supabase.functions.invoke('kvkk-consent',{body:{version,noticeAccepted:true,explicitConsent}});if(error)throw error;evidence={...evidence,...data,channel:'supabase-edge-function'}}catch(err){setBusy(false);notify('KVKK onayı API üzerinden kaydedilemedi: '+(err.message||err));return}}setS(x=>({...x,users:x.users.map(u=>u.id===user.id?{...u,kvkkConsentAt:at,kvkkConsentEvidence:evidence}:u),settings:{...x.settings,kvkkAccepted:{...(x.settings.kvkkAccepted||{}),[user.id]:at},kvkkAudit:[...(x.settings.kvkkAudit||[]),evidence]}}));setBusy(false)};return <div className="auth"><div className="auth-card kvkk-consent"><img src="/arya-logo.png"/><h1>KVKK Aydınlatma ve Onay</h1><p>ARYA Akademi; kimlik, iletişim, firma/çalışma, eğitim, sınav ve sertifika verilerinizi eğitim yönetimi, yetkinlik takibi, belgelendirme ve yasal kayıt süreçleri için işler. Onay kaydı API işlem kimliği, metin sürümü, kullanıcı hesabı, tarih-saat, istemci bilgisi ve sunucu tarafından görülen IP bilgisiyle denetim kaydına alınır.</p><label className="consent-line"><input type="checkbox" checked={notice} onChange={e=>setNotice(e.target.checked)}/> KVKK Aydınlatma Metnini okudum ve gerekli bilgilendirmeyi aldım.</label><label className="consent-line"><input type="checkbox" checked={explicitConsent} onChange={e=>setExplicitConsent(e.target.checked)}/> Açık rıza gerektiren isteğe bağlı veri işleme faaliyetlerine açık rıza veriyorum. (İsteğe bağlı)</label><button className="primary" disabled={!notice||busy} onClick={accept}>{busy?'Kaydediliyor…':'Onayı Kaydet ve Devam Et'}</button><small>Metin sürümü: KVKK-2026-08-v1</small></div></div>}
function KvkkAudit({s}){const rows=s.settings.kvkkAudit||[];return <Panel title="KVKK Onay Kanıtları">{rows.length?<div className="table"><div className="tr th"><span>Kullanıcı</span><span>Sürüm</span><span>Tarih</span><span>Kanal / API</span><span>Kanıt ID</span></div>{rows.slice().reverse().map(r=><div className="tr" key={r.id}><span>{s.users.find(u=>u.id===r.userId)?.name||r.userId}</span><span>{r.version}</span><span>{fmtDate(r.acceptedAt||r.accepted_at)}</span><span>{r.channel||'API'}</span><span>{r.id}</span></div>)}</div>:<Empty title="Henüz KVKK onayı yok" text="Firma/katılımcı ilk girişte onay verdiğinde API kanıtı burada görünür."/>}</Panel>}
function Settings({s,setS,notify,online}){const[tab,setTab]=useState('general'),[installPrompt,setInstallPrompt]=useState(null);useEffect(()=>{const h=e=>{e.preventDefault();setInstallPrompt(e)};window.addEventListener('beforeinstallprompt',h);return()=>window.removeEventListener('beforeinstallprompt',h)},[]);const save=e=>{e.preventDefault();const f=new FormData(e.currentTarget);setS(x=>({...x,settings:{...x.settings,certificatePrefix:f.get('prefix')||x.settings.certificatePrefix||'ARYA',defaultDueDays:Number(f.get('dueDays')||x.settings.defaultDueDays||30),defaultLinkDays:Number(f.get('linkDays')||x.settings.defaultLinkDays||30),certificateSigner:f.get('signer')||x.settings.certificateSigner||'ARYA Akademi',certificateTitle:f.get('certTitle')||x.settings.certificateTitle||'Başarı Sertifikası',certificateNote:f.get('certificateNote')??x.settings.certificateNote}}));notify('Ayarlar kaydedildi.')};const install=async()=>{if(!installPrompt){notify('Uygulama zaten kurulu olabilir veya tarayıcı kurulum seçeneğini adres çubuğunda gösteriyor.');return}await installPrompt.prompt();setInstallPrompt(null)};return <><div className="tabs admin-tabs"><button className={tab==='general'?'active':''} onClick={()=>setTab('general')}>Genel</button><button className={tab==='certificate'?'active':''} onClick={()=>setTab('certificate')}>Sertifika</button><button className={tab==='offline'?'active':''} onClick={()=>setTab('offline')}>Çevrimdışı / PWA</button><button className={tab==='system'?'active':''} onClick={()=>setTab('system')}>Sistem</button></div><form onSubmit={save}>{tab==='general'&&<Panel title="Eğitim ve Atama Ayarları"><div className="form"><label>Varsayılan eğitim son tarihi (gün)<input name="dueDays" type="number" min="1" max="365" defaultValue={s.settings.defaultDueDays||30}/></label><label>Mobil link varsayılan geçerlilik süresi (gün)<input name="linkDays" type="number" min="1" max="180" defaultValue={s.settings.defaultLinkDays||30}/></label><button className="primary">Ayarları Kaydet</button></div></Panel>}{tab==='certificate'&&<Panel title="Sertifika Ayarları"><div className="form"><label>Sertifika numarası öneki<input name="prefix" defaultValue={s.settings.certificatePrefix||'ARYA'}/></label><label>Türkçe sertifika başlığı<input name="certTitle" defaultValue={s.settings.certificateTitle||'Başarı Sertifikası'}/></label><label>İmza / Düzenleyen<input name="signer" defaultValue={s.settings.certificateSigner||'ARYA Akademi'}/></label><label>Notlar (isteğe bağlı)<textarea name="certificateNote" rows="3" defaultValue={s.settings.certificateNote||''} placeholder="Sertifikanın sağ alt köşesinde gösterilecek not"/></label><p className="muted">Sertifikalar gerçek A4 yatay baskı penceresinde Türkçe ve İngilizce olarak üretilir ve QR ile doğrulanır.</p><button className="primary">Sertifika Ayarlarını Kaydet</button></div></Panel>}{tab==='offline'&&<Panel title="Çevrimdışı Kullanım"><div className="offline-status"><div><b>{online?'Çevrimiçi':'Çevrimdışı'}</b><span>Bağlantı durumu</span></div><div><b>Aktif</b><span>Service Worker / PWA</span></div><div><b>Aktif</b><span>Yerel eğitim ve durum önbelleği</span></div><div><b>Otomatik</b><span>Bağlantı gelince senkronizasyon</span></div></div><p className="muted">Daha önce açılmış sabit eğitim içerikleri ve uygulama ekranları çevrimdışı kullanılabilir. Yeni giriş, dosya yükleme, mobil link ilk doğrulaması, sınav sonuçlandırma ve sertifika üretimi güvenlik nedeniyle internet gerektirir.</p><button type="button" className="primary" onClick={install}>Bu Cihaza Uygulama Olarak Kur</button></Panel>}{tab==='system'&&<Panel title="Sistem Durumu"><div className="settings"><div><b>Sürüm</b><span>2.8.0</span></div><div><b>Katılımcı / Firma</b><span>{s.companies.length}</span></div><div><b>Çalışan</b><span>{s.users.filter(u=>u.role==='participant'&&u.employmentType!=='contractor').length}</span></div><div><b>Taşeron Çalışan</b><span>{s.users.filter(u=>u.role==='participant'&&u.employmentType==='contractor').length}</span></div><div><b>Eğitim</b><span>{s.courses.length}</span></div><div><b>Atama</b><span>{s.assignments.length}</span></div><div><b>Sertifika</b><span>{s.certificates.length}</span></div><div><b>Mobil Katılım</b><span>{(s.mobileAccess||[]).length}</span></div><div><b>Veritabanı</b><span>{configured?'Supabase bağlı':'Demo / yerel'}</span></div></div></Panel>}</form></>}
function MobileTraining({token}){const[pin,setPin]=useState(''),[data,setData]=useState(null),[msg,setMsg]=useState(''),[step,setStep]=useState(0),[exam,setExam]=useState(false),[answers,setAnswers]=useState({}),[result,setResult]=useState(null);const verify=async e=>{e.preventDefault();setMsg('');if(!configured){setMsg('Mobil katılım canlı Supabase bağlantısında çalışır.');return}if(!isOnline()){setMsg('İlk doğrulama için internet bağlantısı gerekir.');return}const {data:r,error}=await supabase.rpc('get_mobile_training',{p_token:token,p_pin:pin});if(error||!r?.ok){setMsg(r?.message||error?.message||'Bağlantı doğrulanamadı.');return}setData(r)};if(!data)return <div className="mobile-shell"><div className="mobile-card"><img src="/arya-logo.png"/><h1>ARYA Akademi</h1><h2>Mobil Eğitim Katılımı</h2><p>Kişisel eğitim bağlantınızı doğrulayın.</p><form className="form" onSubmit={verify}><input value={pin} onChange={e=>setPin(e.target.value)} placeholder="PIN / telefon son 4 hane" minLength="4" required/><button className="primary">Eğitime Gir</button></form>{msg&&<div className="notice">{msg}</div>}</div></div>;const c=data.course,qs=c.examQuestions||[],lessons=[...(c.modules||[]).map(x=>({...x,kind:'arya'})),...(c.customContents||[]).map(x=>({id:x.id,title:x.title,body:x.body||'',bullets:[],url:x.url,kind:'custom'}))];const next=async()=>{const n=step+1,p=Math.round(Math.min(n,lessons.length)/(lessons.length||1)*100);if(configured&&isOnline())await supabase.rpc('mobile_set_progress',{p_token:token,p_pin:pin,p_progress:p});if(n>=lessons.length)setExam(true);else setStep(n)};const finish=async()=>{if(Object.keys(answers).length<qs.length){setMsg('Lütfen tüm soruları cevaplayın.');return}if(!isOnline()){setMsg('Sınav sonucu ve sertifika için internet bağlantısı gerekir.');return}const {data:r,error}=await supabase.rpc('submit_mobile_exam',{p_token:token,p_pin:pin,p_answers:answers});if(error||!r?.ok){setMsg(r?.message||error?.message);return}setResult(r)};const l=lessons[step];return <div className="mobile-shell"><div className="mobile-course"><div className="mobile-head"><img src="/arya-logo.png"/><div><b>{data.employeeName}</b><span>{c.title}</span></div></div>{!exam?<><div className="progress"><i style={{width:`${Math.round((step+1)/(lessons.length||1)*100)}%`}}/></div>{l&&<article className={`lesson ${l.kind==='custom'?'custom':''}`}><span>BÖLÜM {step+1}/{lessons.length}</span><h2>{l.title}</h2>{l.body&&<p>{l.body}</p>}{l.bullets?.length>0&&<ul>{l.bullets.map(x=><li key={x}>{x}</li>)}</ul>}{l.url&&<a className="content-link" href={l.url} target="_blank" rel="noreferrer">Ek İçeriği Aç</a>}</article>}<button className="primary mobile-next" onClick={next}>{step===lessons.length-1?'Sınava Geç':'Sonraki Bölüm'}</button></>:<>{!result&&<div className="exam"><h2>Değerlendirme Sınavı</h2><p>Geçme puanı %{c.passing}. Sertifika için sonuç çevrimiçi doğrulanır.</p>{qs.map((q,i)=><div className="exam-q" key={q.id}><b>{i+1}. {q.text}</b>{q.options.map((o,j)=><label key={o}><input type="radio" name={q.id} value={j} checked={String(answers[q.id])===String(j)} onChange={()=>setAnswers(prev=>({...prev,[q.id]:j}))}/><span>{o}</span></label>)}</div>)}<button className="primary" onClick={finish}>Sınavı Tamamla</button>{msg&&<div className="notice">{msg}</div>}</div>}{result&&<div className={`mobile-result ${result.passed?'ok':'bad'}`}><h1>%{result.score}</h1><h2>{result.passed?'Tebrikler!':'Tekrar deneyin'}</h2><p>{result.passed?`Sertifika numaranız: ${result.certificateNo}`:`Geçme puanı %${result.passing}.`}</p>{result.passed&&<a href={`/?verify=${result.certificateNo}`}>Sertifikayı Doğrula</a>}{!result.passed&&<button onClick={()=>setResult(null)}>Tekrar Sınava Gir</button>}</div>}</>}</div></div>}
function Kiosk(){const[employeeNo,setEmployeeNo]=useState(''),[pin,setPin]=useState(''),[items,setItems]=useState([]),[msg,setMsg]=useState('');const find=async e=>{e.preventDefault();if(!configured||!isOnline()){setMsg('Kiosk doğrulaması için internet bağlantısı gerekir.');return}const {data,error}=await supabase.rpc('get_kiosk_trainings',{p_employee_no:employeeNo,p_pin:pin});if(error||!data?.ok){setMsg(data?.message||error?.message||'Eğitim bulunamadı.');setItems([]);return}setItems(data.items);setMsg('')};return <div className="mobile-shell"><div className="mobile-card kiosk"><img src="/arya-logo.png"/><h1>Ortak Tablet / Kiosk</h1><p>Telefonu veya e-posta hesabı olmayan çalışanlar için.</p><form className="form" onSubmit={find}><input value={employeeNo} onChange={e=>setEmployeeNo(e.target.value)} placeholder="Personel / Sicil No" required/><input value={pin} onChange={e=>setPin(e.target.value)} placeholder="PIN" minLength="4" required/><button className="primary">Eğitimlerimi Bul</button></form>{msg&&<div className="notice">{msg}</div>}{items.map(x=><a className="kiosk-course" key={x.token} href={`/?join=${x.token}`}><b>Eğitime Başla</b><span>Son tarih: {fmtDate(x.due)}</span></a>)}<a href="/">Yönetici girişine dön</a></div></div>}

function VerifyPage({id,localState}){const[row,setRow]=useState(null),[loading,setLoading]=useState(true);useEffect(()=>{(async()=>{if(configured){const{data}=await supabase.from('certificate_registry').select('*').eq('certificate_no',id).maybeSingle();setRow(data||null)}else{const c=localState.certificates.find(x=>x.id===id);if(c){const u=localState.users.find(x=>x.id===c.userId),course=localState.courses.find(x=>x.id===c.courseId);setRow({certificate_no:c.id,holder_name:u?.name,course_title:course?.title,score:c.score,issued_at:c.issuedAt,expires_at:c.expiresAt,status:c.status||'valid'})}}setLoading(false)})()},[id]);if(loading)return <div className="verify-page"><div className="verify-card">Doğrulanıyor…</div></div>;const expired=row?.expires_at&&new Date(row.expires_at)<new Date();const valid=row&&row.status!=='revoked'&&!expired;return <div className="verify-page"><div className="verify-card"><img src="/arya-logo.png"/><h1>Sertifika Doğrulama</h1>{row?<><div className={valid?'verify-ok':'verify-bad'}>{valid?'✓ GEÇERLİ SERTİFİKA':expired?'SÜRESİ DOLMUŞ SERTİFİKA':'İPTAL EDİLMİŞ SERTİFİKA'}</div><h2>{row.holder_name}</h2><p>{row.course_title}</p><dl><dt>Sertifika No</dt><dd>{row.certificate_no}</dd><dt>Başarı</dt><dd>%{row.score}</dd><dt>Düzenlenme</dt><dd>{fmtDate(row.issued_at)}</dd><dt>Geçerlilik</dt><dd>{fmtDate(row.expires_at)}</dd></dl></>:<div className="verify-bad">Bu numarayla kayıtlı sertifika bulunamadı.</div>}<a href="/">ARYA Akademi'ye dön</a></div></div>}
function Modal({title,close,children,wide=false}){return <div className="modal-bg" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className={`modal ${wide?'wide':''}`}><div className="modal-head"><h3>{title}</h3><button onClick={close}>×</button></div>{children}</div></div>}
